    /// <summary>
    /// descent - The parachute ride. Cranberry cannot change how FAST the player falls - the August
    /// client simulates the parachute itself off its own MoveInfo rows 130 and 4001 for vehicle 13
    /// - and the 2026-09-03 audit proved the rate is not even a constant: it is a PLAYER-CONTROLLED
    /// 10-56 m/s band, 43.5-45.8 m/s flown hard and 9.8 m/s hands-off. So the only server lever is
    /// the release altitude. D238 ships ClientSkySpawn850 - the client's own KotK.SkySpawn slab
    /// centre, an absolute 850 m - replacing D125's Legacy36 design number, which was
    /// reverse-engineered from the friend's emulator's 1500 m and not from retail. Legacy36 stays
    /// reachable by name as the revert. D239 rebuilds the descent deadline around the 10 m/s
    /// hands-off worst case and gates the forced handover on the chute actually being near the
    /// ground.
    /// <para>
    /// Source: <c>rulings/descent.json</c>. Rulings: D66, D125, D127, D128, D238, D239, D240.
    /// </para>
    /// </summary>
    public static class Descent
    {
        /// <summary>
        /// DescentTuning.MinimumRate = 10.0. Ruling none. Grade CLIENT.
        /// <para>
        /// Source: the client's own MoveInfo row 4001 MIN_TERM_VELOCITY for vehicle 13
        /// </para>
        /// <para>
        /// NOT a ruling - a client rail, transcribed into C# as a validation bound. D239 promotes
        /// it: it is also the HANDS-OFF descent rate, measured at 9.81 / 9.85 / 9.82 m/s in
        /// logs/host-20260903-082114, -082424 and -083422, so every server TIMEOUT reasons with
        /// this number and not with the dived mean.
        /// </para>
        /// </summary>
        public const float MinimumRate = 10.0f;

        /// <summary>
        /// DescentTuning.MaximumRate = 56.0. Ruling none. Grade CLIENT.
        /// <para>
        /// Source: the client's own MoveInfo row 4001 MAX_TERM_VELOCITY for vehicle 13
        /// </para>
        /// <para>
        /// NOT a ruling - a client rail. Every 'too fast' check must use this number.
        /// </para>
        /// </summary>
        public const float MaximumRate = 56.0f;

        /// <summary>
        /// DescentSettings.MeasuredHandsOffMetresPerSecond = 9.8. Ruling none. Grade CAPTURED.
        /// <para>
        /// Source: AUDIT-parachute R7 - logs/host-20260903-082114.log:165-201 (9.81 m/s),
        /// -082424.log (9.85), -083422.log (9.82); X frozen for the whole 84 s and Z drifting 15 m
        /// in all three
        /// </para>
        /// <para>
        /// UNRULED - a measurement. It is MIN_TERM_VELOCITY 10 within 2 %, which is the proof that
        /// the client's own floor is reachable and that a player who lets go of the controls really
        /// does take (fall / 10) seconds to land. Pinned so a later lane cannot re-derive 40.4 as
        /// 'the' rate.
        /// </para>
        /// </summary>
        public const float MeasuredHandsOffMetresPerSecond = 9.8f;

        /// <summary>
        /// DescentSettings.MeasuredFlownMetresPerSecond = 45.8. Ruling none. Grade CAPTURED.
        /// <para>
        /// Source: AUDIT-parachute R7/section 2 - steady windows of the two 2026-09-03 17:50 /
        /// 17:59 rides, 43.5-45.8 m/s; out/audit/descent-measurements-20260903.md
        /// </para>
        /// <para>
        /// UNRULED - the top of the measured flown band, and the number a 'shortest possible ride'
        /// estimate uses. The first ~5 s of every ride is 14.8-22.0 m/s while the canopy opens.
