        /// </para>
        /// <para>
        /// THE GATE THAT MAKES D239 SAFE. A chute whose last reported Y is more than this above the
        /// drop's ground is flying, whatever the clock says, and is never dismounted by the server.
        /// The doubling is Cranberry's, to absorb the terrain difference between the planned marker
        /// and where the player actually glided to (587-672 m away, measured).
        /// </para>
        /// </summary>
        public const float GroundProximityMetres = 40.0f;

