        /// </para>
        /// <para>
        /// UNRULED, DESIGN. A chute whose channel-3 pose stream has been silent this long is not
        /// being flown by anybody, so forcing the handover cannot interrupt a live ride. Twenty
        /// seconds is 200 pump ticks and ~20 missed 10 Hz managed records.
        /// </para>
        /// </summary>
        public const double StreamSilenceSeconds = 20.0d;

        /// <summary>
